import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import { Line, Bar } from 'react-chartjs-2';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

export const TARGET_PROFILES = {
  Crop_Yield: {
    label: 'Crop Yield',
    unit: 'tons/ha',
    description: 'Quezon City vegetable harvest yield instability indicator',
    sarimaCandidates: [
      { params: '(1, 1, 1) (1, 0, 1)s', aic: 120, rmse: 0.12, mae: 0.08, mape: '5.8%', status: '★ Minimum AIC (Config 1)', isBest: true },
      { params: '(1, 0, 1) (0, 1, 1)s', aic: 126, rmse: 0.15, mae: 0.09, mape: '6.8%', status: 'Config 2 (Runner-Up)', isRunnerUp: true },
      { params: '(0, 1, 1) (1, 1, 1)s', aic: 140, rmse: 0.19, mae: 0.12, mape: '8.4%', status: 'Evaluated' },
      { params: '(1, 1, 0) (1, 0, 1)s', aic: 122, rmse: 0.14, mae: 0.09, mape: '6.1%', status: 'Evaluated' }
    ],
    config1: { params: '(1, 1, 1) (1, 0, 1)s', aic: 120, rmse: 0.12, mae: 0.08, mape: '5.8%' },
